package com.arjun.signagekioskautousb;import android.app.*;import android.content.*;import android.os.*;public class StartupService extends Service{private Handler h;@Override public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel("signage","Signage",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);startForeground(7,new Notification.Builder(this,"signage").setContentTitle("AP Signage").setContentText("Startup monitor").setSmallIcon(R.drawable.ic_signage).build());}h=new Handler(Looper.getMainLooper());h.postDelayed(new Runnable(){public void run(){try{Intent a=new Intent(StartupService.this,MainActivity.class);a.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT);startActivity(a);}catch(Exception ignored){}h.postDelayed(this,30000);}},5000);}@Override public int onStartCommand(Intent i,int f,int id){return START_STICKY;}@Override public IBinder onBind(Intent i){return null;}}